import SwiftUI

struct PlantLinkRouter {
    let openURL: OpenURLAction

    /// Called with the raw `?share=` value from a link another user sent.
    func openShared(slug: String) {
        let url = URL(string: "https://plants.example.com/p/\(slug)")!
        openURL(url)
    }

    func openSettings() {
        if let url = URL(string: UIApplication.openSettingsURLString) {
            openURL(url)
        }
    }
}
